"use strict";webui.define("app-project-manager",{constructor(){const t=this;t._btnEdit=t.template.querySelector("#btn-edit"),t._btnRemove=t.template.querySelector("#btn-remove")},connected(){const t=this;t._btnEdit.addEventListener("click",async l=>{let e=webui.getData("app-current-project");if(!e||!e.value){webui.alert("No project is currently selected.","warning");return}webui.dialog({title:"Rename Project",content:`
                        <webui-flex column><webui-input-text name="projectName" label="New Project Name" value="${e.display}">
                        </webui-input-text></webui-flex>
                        `,confirm:"Rename",cancel:"Cancel",onconfirm:async(o,a)=>{let r=(Object.fromEntries(o).projectName||"").trim();if(!r)return a.alert("Project name cannot be empty."),!1;let i=await webui.proxy.renameProject(e.value,r,c=>a.alert(c));if(i)return webui.alert(i,"success"),webui.setData("app-current-project",{value:e.value,display:r}),!0}})}),t._btnRemove.addEventListener("click",async l=>{let e=webui.getData("app-current-project");if(!e||!e.value){webui.alert("No project is currently selected.","warning");return}webui.dialog({title:"Remove Project",content:`
                    <p>Are you sure you want to remove the project <strong>${e.display}</strong>?</p>
                    <p style="color: var(--color-danger);">This will only remove the project from Task Proxy. No files or folders will be deleted.</p>
                    `,confirm:"Remove",cancel:"Cancel",onconfirm:async(o,a)=>{let n=await webui.proxy.removeProject(e.value,r=>a.alert(r));if(n)return webui.alert(n,"success"),webui.setData("app-current-project",null),!0}})})},shadowTemplate:`
<style type="text/css">
:host {
    display: flex;
    gap: var(--padding);
    flex-wrap: wrap;
}
</style>
<webui-page-segment>
<webui-flex align="center" justify="start">
<webui-button id="btn-edit" theme="primary">Edit Name</webui-button>
<webui-button id="btn-remove" theme="danger">Remove Project</webui-button>
</webui-flex>
</webui-page-segment>`});
